class Solution {
public:
    std::vector<int> applyOperations(std::vector<int>& nums) {
        int n = nums.size();
        for (int i = 0; i + 1 < n; ++i) {
            if (nums[i] == nums[i + 1]) {
                nums[i] *= 2;
                nums[i + 1] = 0;
            }
        }
        std::vector<int> res;
        for (int x : nums) if (x != 0) res.push_back(x);
        while (res.size() < (size_t)n) res.push_back(0);
        return res;
    }
};

class Solution {
    public int[] applyOperations(int[] nums) {
        int n = nums.length;
        for (int i = 0; i + 1 < n; i++) {
            if (nums[i] == nums[i + 1]) {
                nums[i] *= 2;
                nums[i + 1] = 0;
            }
        }
        int[] res = new int[n];
        int idx = 0;
        for (int x : nums) {
            if (x != 0) res[idx++] = x;
        }
        return res;
    }
}

var applyOperations = function(nums) {
    const n = nums.length;
    for (let i = 0; i + 1 < n; i++) {
        if (nums[i] === nums[i + 1]) {
            nums[i] *= 2;
            nums[i + 1] = 0;
        }
    }
    const res = nums.filter(x => x !== 0);
    while (res.length < n) res.push(0);
    return res;
};
